// Doomerfall: gold value and weight of Doom weapons, so they can be sold (goal 20261127-095003).
//
// The numbers live in Resources/Doomerfall/WeaponValues.txt, generated by tools/weapon_values/build_weapon_values.py
// for DRLA, stock Doom, Schism, Heretic and Hexen. Each weapon has a weight and a role and tier. Its value is the base
// price of the role's Daggerfall weapon, run through Daggerfall's own material rule (ItemBuilder.CreateWeapon, the
// same as a Daggerfall weapon of that material), times the owner's tier multiplier and the file's scale (0.2, so a
// legendary costs 2x its base weapon). A gun's weight follows its material as a Daggerfall weapon's does. Daggerfall owns the economy, so
// the file and the rule are on Daggerfall's side; Doom is not involved.
//
// Weaponsmiths, armorers, pawn shops and general stores buy Doom weapons, as they buy Daggerfall weapons (owner,
// 2026-11-26), except the gun Doom is holding, as Daggerfall never offers an equipped weapon.

using System;
using System.Collections.Generic;
using System.Globalization;
using DaggerfallWorkshop.Game.Items;
using UnityEngine;

namespace DaggerfallWorkshop.Game.Doomerfall
{
    internal static class DoomerfallWeaponValues
    {
        internal sealed class Entry
        {
            public string weaponClass, set, kind, role, tier, pickup; // pickup: the first world pickup class listed
            public float weightKg, share;
            public Weapons template;
            public int tierMultiplier;
        }

        static Dictionary<string, Entry> byClass;
        static readonly List<Entry> all = new List<Entry>();
        static int cap;
        static double scale = 1; // every value x this (WeaponValues.txt "scale"; owner 2026-11-27: legendary = 2x its base weapon)
        static readonly Dictionary<int, int> materialValue = new Dictionary<int, int>(); // (template, material) -> Daggerfall value
        static readonly Dictionary<int, float> materialWeight = new Dictionary<int, float>(); // (quarter kg, material) -> kg

        // The entry for a Doom item class (a pickup class such as RLPistolPickup, or the weapon class), or null.
        internal static Entry Find(string doomClass)
        {
            Load();
            if (string.IsNullOrEmpty(doomClass))
                return null;
            Entry e;
            return byClass.TryGetValue(doomClass, out e) ? e : null;
        }

        // A set's weapons (as WeaponValues.txt names sets: DRLA, Doom, Heretic, Hexen, Schism), without fists, in file order.
        internal static List<Entry> InSet(string set)
        {
            Load();
            return all.FindAll(e => string.Equals(e.set, set, StringComparison.OrdinalIgnoreCase) && e.role != "unarmed");
        }

        // The weight Daggerfall gives a Doom weapon of this material. The file's weight is the Iron weight. Other materials change it by Daggerfall's own rule for its weapons
        // (ItemBuilder.SetItemPropertiesByMaterial: Dwarven x0.75, Ebony x0.5, Steel and Daedric x1.25, in quarter kg),
        // run on a scratch item so the rule stays Daggerfall's (owner, 2026-11-27, Q&A item 38).
        internal static float WeightOf(Entry e, WeaponMaterialTypes material)
        {
            int key = (int)Math.Round(e.weightKg * 4) * 16 + (int)material;
            float weight;
            if (!materialWeight.TryGetValue(key, out weight))
            {
                DaggerfallUnityItem scratch = new DaggerfallUnityItem { weightInKg = e.weightKg };
                materialWeight[key] = weight = ItemBuilder.SetItemPropertiesByMaterial(scratch, material).weightInKg;
            }
            return weight;
        }

        // Gold value before shop pricing, for a weapon of this class and Daggerfall material. The file's scale shrinks
        // every value by one factor, so proportions stay; integer gold rounds the cheapest, and nothing falls below 1.
        internal static int ValueOf(Entry e, WeaponMaterialTypes material)
        {
            int key = (int)e.template * 16 + (int)material, baseValue;
            if (!materialValue.TryGetValue(key, out baseValue))
                materialValue[key] = baseValue = ItemBuilder.CreateWeapon(e.template, material).value;
            long value = Math.Max(1, (long)Math.Round((double)baseValue * e.tierMultiplier * e.share * scale));
            if (cap > 0 && value > cap)
                value = cap;
            return (int)Math.Min(value, int.MaxValue);
        }

        // Gives a Doom item its weight and value from the file. Items without an entry keep what they have.
        internal static void Apply(DoomerfallDoomItem item)
        {
            Entry e = Find(item.DoomClass);
            if (e == null)
                return;
            WeaponMaterialTypes material = item.IsGun ? item.Material : WeaponMaterialTypes.Iron;
            item.weightInKg = WeightOf(e, material);
            item.value = ValueOf(e, material);
        }

        // Whether a shop that buys these item groups buys this item: a Doom weapon with a value, where the shop buys
        // weapons, and not the gun Doom holds.
        internal static bool SellsHere(DaggerfallUnityItem item, List<ItemGroups> accepted)
        {
            DoomerfallDoomItem doom = item as DoomerfallDoomItem;
            if (doom == null || !accepted.Contains(ItemGroups.Weapons) || Find(doom.DoomClass) == null)
                return false;
            return DoomerfallHotkeys.Instance == null || DoomerfallHotkeys.Instance.ActiveGun != doom;
        }

        static void Load()
        {
            if (byClass != null)
                return;
            byClass = new Dictionary<string, Entry>(StringComparer.OrdinalIgnoreCase);
            TextAsset text = Resources.Load<TextAsset>("Doomerfall/WeaponValues");
            if (text == null)
            {
                Debug.LogError("Doomerfall: Resources/Doomerfall/WeaponValues.txt is missing; Doom weapons have no value.");
                return;
            }
            Dictionary<string, Weapons> roles = new Dictionary<string, Weapons>();
            Dictionary<string, int> tiers = new Dictionary<string, int>();
            foreach (string raw in text.text.Split('\n'))
            {
                string line = raw.Trim();
                if (line.Length == 0 || line[0] == '#')
                    continue;
                string[] f = line.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
                try
                {
                    if (f[0] == "cap" && f.Length >= 2)
                        cap = int.Parse(f[1], CultureInfo.InvariantCulture);
                    else if (f[0] == "scale" && f.Length >= 2)
                        scale = double.Parse(f[1], CultureInfo.InvariantCulture);
                    else if (f[0] == "role" && f.Length >= 3)
                        roles[f[1]] = (Weapons)Enum.Parse(typeof(Weapons), f[2]);
                    else if (f[0] == "tier" && f.Length >= 3)
                        tiers[f[1]] = int.Parse(f[2], CultureInfo.InvariantCulture);
                    else if (f[0] == "weapon" && f.Length >= 9)
                    {
                        Entry e = new Entry
                        {
                            weaponClass = f[1], set = f[2], kind = f[3], role = f[4], tier = f[5],
                            weightKg = float.Parse(f[6], CultureInfo.InvariantCulture),
                            share = float.Parse(f[7], CultureInfo.InvariantCulture),
                            template = roles[f[4]], tierMultiplier = tiers[f[5]],
                            pickup = f[8].Split(',')[0],
                        };
                        byClass[e.weaponClass] = e;
                        all.Add(e);
                        foreach (string pickup in f[8].Split(','))
                            if (pickup.Length > 0)
                                byClass[pickup] = e;
                    }
                }
                catch (Exception ex)
                {
                    Debug.LogError("Doomerfall: bad WeaponValues.txt line \"" + line + "\": " + ex.Message);
                }
            }
        }
    }
}
